    68	        // 사용자 이메일 추출 및 검증
    69	        String email = SecurityUtils.extractAndValidateEmailForOrderBid("주문 입찰 삭제");
    70	
    71	        log.info("사용자 [{}]가 주문 입찰(ID: {})의 삭제를 요청합니다.", email, orderBidId);
    72	
    73	        // 서비스 호출
