491	     * 결제 상태 변경
492	     *
493	     * @param payment   상태 변경할 결제 정보
494	     * @param newStatus 새로운 상태
495	     * @throws PaymentException 상태 변경 실패 시
496	     */
497	    @Transactional
498	    public void updatePaymentStatus(Payment payment, PaymentStatus newStatus) {
499	        Instant start = Instant.now();
500	        try {
501	            if (payment == null) {
502	                throw new PaymentNotFoundException("결제 정보가 없습니다.");
503	            }
504	
